#!/usr/bin/env bash
# Creates .env with fresh random secrets for local use and docker compose.
# Never overwrites an existing .env.
set -euo pipefail

if [[ -e .env ]]; then
  echo ".env already exists; leaving it alone. Delete it to start over."
  exit 0
fi

# 32 random bytes as base64url without padding: the format the signing keys use.
b64url32() { head -c 32 /dev/urandom | base64 | tr '+/' '-_' | tr -d '=\n'; }

umask 077 # only you can read the file
cat > .env <<ENV
# Generated by scripts/setup-env.sh. Secrets: never commit this file.
CONSEQUENCE_KEY_SUPPORT_BOT=$(b64url32)
CONSEQUENCE_ADMIN_TOKEN=$(b64url32)
CONSEQUENCE_SIGNING_KEY_ED25519=$(b64url32)
CONSEQUENCE_SIGNING_KEY_MLDSA87=$(b64url32)
POSTGRES_PASSWORD=$(b64url32)
ENV
echo "Wrote .env with fresh secrets."
